"""Generate portable, crawlable HTML. Run with Python 3; no packages required."""
from pathlib import Path
from html import escape as esc
import json, os
from urllib.parse import urlencode
ROOT=Path(__file__).resolve().parents[1]
site=json.loads((ROOT/'data/site.json').read_text(encoding='utf-8'))
tours=json.loads((ROOT/'data/tours.json').read_text(encoding='utf-8'))['tours']
dests=json.loads((ROOT/'data/destinations.json').read_text(encoding='utf-8'))['destinations']
images=json.loads((ROOT/'data/images.json').read_text(encoding='utf-8'))
articles=json.loads((ROOT/'data/articles.json').read_text(encoding='utf-8'))['articles']
testimonials=json.loads((ROOT/'data/testimonials.json').read_text(encoding='utf-8'))
pages=[]
current='index.html'
CATEGORY_ORDER=['Sahara escapes','Cities & desert','Grand journeys']
HOME_TOUR_SLUGS=['5-day-casablanca-marrakech','2-day-mhamid-desert','7-day-grand-morocco']
UPLOAD_ROOT=(ROOT/'images/uploads').resolve()
def link(path):
 return os.path.relpath(path, str(Path(current).parent)).replace(os.sep,'/')
def a(path,text,cls=''):
 return f'<a href="{esc(link(path),quote=True)}" class="{cls}">{text}</a>'
def content_image(item):
 return item.get('uploaded_image') or item['image']
def uploaded_image_path(value):
 relative=str(value).replace('\\','/').lstrip('/')
 candidate=(ROOT/relative).resolve()
 if not relative.startswith('images/uploads/') or not candidate.is_relative_to(UPLOAD_ROOT):
  raise ValueError(f'Uploaded image must be inside images/uploads: {value}')
 if not candidate.is_file():raise ValueError(f'Uploaded image does not exist: {value}')
 return relative,candidate
def image_dimensions(path):
 data=path.read_bytes()
 if data.startswith(b'\x89PNG\r\n\x1a\n') and len(data)>=24:return int.from_bytes(data[16:20],'big'),int.from_bytes(data[20:24],'big')
 if data[:6] in (b'GIF87a',b'GIF89a') and len(data)>=10:return int.from_bytes(data[6:8],'little'),int.from_bytes(data[8:10],'little')
 if data.startswith(b'\xff\xd8'):
  offset=2
  sof={0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf}
  while offset+4<=len(data):
   while offset<len(data) and data[offset]==0xff:offset+=1
   if offset>=len(data):break
   marker=data[offset];offset+=1
   if marker in (0x01,0xd8,0xd9):continue
   if offset+2>len(data):break
   size=int.from_bytes(data[offset:offset+2],'big')
   if marker in sof and offset+7<=len(data):return int.from_bytes(data[offset+3:offset+5],'big'),int.from_bytes(data[offset+5:offset+7],'big')
   if size<2:break
   offset+=size
 if data[:4]==b'RIFF' and data[8:12]==b'WEBP' and len(data)>=30:
  if data[12:16]==b'VP8X':return 1+int.from_bytes(data[24:27],'little'),1+int.from_bytes(data[27:30],'little')
  if data[12:16]==b'VP8 ' and data[23:26]==b'\x9d\x01\x2a':return int.from_bytes(data[26:28],'little')&0x3fff,int.from_bytes(data[28:30],'little')&0x3fff
  if data[12:16]==b'VP8L' and len(data)>=25 and data[20]==0x2f:
   bits=int.from_bytes(data[21:25],'little');return 1+(bits&0x3fff),1+((bits>>14)&0x3fff)
 raise ValueError(f'Unsupported or invalid image: {path.relative_to(ROOT)}')
def image_url(value):
 if value in images:return site['url'].rstrip('/')+f'/assets/images/{value}-960.webp'
 relative,_=uploaded_image_path(value)
 return site['url'].rstrip('/')+'/'+relative
def img(key,alt,cls='',eager=False):
 sizes='100vw' if cls=='hero-photo' else '(max-width: 640px) 92vw, (max-width: 1000px) 46vw, 33vw'
 if cls=='article-photo':sizes='(max-width: 560px) calc(100vw - 36px), (max-width: 1100px) calc(100vw - 56px), (max-width: 1336px) calc(100vw - 96px), 1240px'
 if cls=='blog-featured-photo':sizes='(max-width: 560px) 92vw, 46vw'
 if key not in images:
  relative,path=uploaded_image_path(key);width,height=image_dimensions(path)
  return f'<img class="{cls}" src="{esc(link(relative),quote=True)}" width="{width}" height="{height}" alt="{esc(alt,quote=True)}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
 widths=[480,960,1600] if key=='sahara' else [480,960]
 srcset=', '.join(f'{link(f"assets/images/{key}-{w}.webp")} {min(w,images[key]["width"])}w' for w in widths)
 return f'<img class="{cls}" src="{link(f"assets/images/{key}-960.webp")}" srcset="{srcset}" sizes="{sizes}" width="{images[key]["width"]}" height="{images[key]["height"]}" alt="{esc(alt,quote=True)}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
def brand():
 return f'<img class="brand-logo" src="{link("assets/logo-morocco-explorer-tours.png")}" width="1008" height="687" alt="Morocco Explorer Tours">'
def homepage_tours():
 by_slug={t['slug']:t for t in tours}
 return [by_slug[slug] for slug in HOME_TOUR_SLUGS if slug in by_slug]
def filter_options(values):
 return ''.join(f'<option>{esc(str(value))}</option>' for value in values)
def duration_options():
 return ''.join(f'<option value="{days}">{days} days</option>' for days in sorted({t["days"] for t in tours}))
def header():
 nav=''.join(a(p,t,'active' if current==p or (p=='blog/index.html' and current.startswith('blog/')) else '') for p,t in [('tours/index.html','Our tours'),('destinations/index.html','Destinations'),('blog/index.html','Blog'),('about.html','Our story')])
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container header-inner">{a('index.html',brand(),'brand')}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation" hidden>Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{nav}{a('plan-your-trip.html','Plan your trip <span aria-hidden="true">↗</span>','button small')}</nav></div></header>'''
def footer():
 return f'''<footer><div class="container footer-grid"><div>{a('index.html',brand(),'brand')}<p>Private journeys through Morocco.<br>Thoughtfully planned. Personally explored.</p><span class="footer-location">MARRAKECH · MOROCCO</span></div><div><h2>Explore</h2>{a('tours/index.html','All journeys')}{a('tours/index.html?category=Sahara+escapes','Sahara escapes')}{a('tours/index.html?category=Cities+%26+desert','Cities &amp; desert')}{a('tours/index.html?category=Grand+journeys','Grand journeys')}</div><div><h2>Get to know us</h2>{a('blog/index.html','Travel blog')}{a('destinations/index.html','Our destinations')}{a('about.html','Our story')}{a('index.html#questions','Common questions')}{a('privacy.html','Privacy Policy')}{a('terms-and-conditions.html','Terms and Conditions')}</div><div><h2>A journey of your own</h2><p>Have a place in mind?<br>Start with what inspires you.</p>{a('plan-your-trip.html','Create your trip brief ↗','footer-plan')}</div></div><div class="container footer-bottom"><span>© 2026 Morocco Explorer Tours</span><span>Desert roads. Medina moments. Your Morocco.</span>{a('sitemap.xml','Sitemap')}</div></footer>'''
def cta():
 return f'<section class="cta container"><div><p class="eyebrow">MAKE IT PERSONAL</p><h2>Your Morocco starts<br>with a little curiosity.</h2><p>A favourite place, a few dates, a big idea. Build a journey around you.</p></div>{a("plan-your-trip.html","Let’s plan your journey ↗","button light")}</section>'
def write(path,title,description,body,section='',schema=None):
 global current
 assert path==current
 canonical=site['url'].rstrip('/')+('/' if path=='index.html' else '/'+path.replace('index.html',''))
 base_schema={'@context':'https://schema.org','@type':'TravelAgency','name':site['name'],'url':site['url'],'areaServed':{'@type':'Country','name':'Morocco'}}
 if schema:base_schema=schema
 if schema and schema.get('@type')=='BlogPosting':
  social_image=schema['image']
  social_alt=next(article['alt'] for article in articles if path=='blog/'+article['slug']+'.html')
 else:
  social_image=site['url']+'/assets/images/sahara-1600.webp'
  social_alt='Camel caravan crossing the dunes at sunset'
 doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | Morocco Explorer Tours</title><meta name="description" content="{esc(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:site_name" content="Morocco Explorer Tours"><meta property="og:image" content="{site['url']}/assets/images/sahara-1600.webp"><meta property="og:image:alt" content="Camel caravan crossing the dunes at sunset"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#703d2b"><link rel="icon" href="{link('assets/favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{link('assets/styles.css')}"><script src="{link('assets/site.js')}" defer></script><script type="application/ld+json">{json.dumps(base_schema).replace('<',chr(92)+'u003c')}</script></head><body class="{section}">{header()}<main id="main">{body}</main>{footer()}</body></html>'''
 doc=doc.replace(f'{site["url"]}/assets/images/sahara-1600.webp',social_image).replace('content="Camel caravan crossing the dunes at sunset"',f'content="{esc(social_alt,quote=True)}"')
 if schema and schema.get('@type')=='BlogPosting':doc=doc.replace('property="og:type" content="website"','property="og:type" content="article"')
 if path=='404.html':doc=doc.replace('<meta name="viewport"', '<meta name="robots" content="noindex, follow"><meta name="viewport"')
 out=ROOT/path;out.parent.mkdir(parents=True,exist_ok=True);out.write_text(doc+'\n',encoding='utf-8');pages.append((path,canonical))
def tourcard(t):
 return f'''<article class="tour-card" data-start="{t['start']}" data-category="{esc(t['category'])}" data-days="{t['days']}"><a class="card-photo" href="{link('tours/'+t['slug']+'.html')}" tabindex="-1" aria-hidden="true">{img(content_image(t),t['title'])}<span class="photo-label">{t['days']} DAYS · {t['nights']} {'NIGHT' if t['nights']==1 else 'NIGHTS'}</span></a><div class="card-body"><p class="eyebrow">{esc(t['category'])}</p><h3>{a('tours/'+t['slug']+'.html',esc(t['name']))}</h3><p class="route-line">{t['start']} <span aria-hidden="true">→</span> {t['end']}</p><p>{t['description']}</p><div class="card-bottom"><span>Private · Tailor-made</span>{a('tours/'+t['slug']+'.html','Explore trip <span aria-hidden="true">↗</span>')}</div></div></article>'''
def destcard(d):
 return f'''<a class="destination-card" href="{link('destinations/'+d['slug']+'.html')}">{img(content_image(d),d['name'])}<div><span>{d['category']}</span><h3>{esc(d['name'])}</h3></div><span class="circle-arrow" aria-hidden="true">↗</span></a>'''

def articlecard(article,heading='h2'):
 path='blog/'+article['slug']+'.html'
 return f'''<article class="blog-card"><a class="card-photo" href="{link(path)}" tabindex="-1" aria-hidden="true">{img(content_image(article),article['alt'],'blog-featured-photo' if heading=='h3' else '')}</a><div class="card-body"><p class="eyebrow">{esc(article['category'])}</p><{heading}>{a(path,esc(article['title']))}</{heading}><p class="blog-teaser">{esc(article['teaser'])}...</p><div class="card-bottom">{a(path,'Read More<span class="sr-only">: '+esc(article['title'])+'</span> <span aria-hidden="true">↗</span>')}</div></div></article>'''

def blog_preview():
 return f'''<section class="section container blog-preview" aria-labelledby="blog-preview-title"><div class="section-heading"><div><p class="eyebrow">THE MOROCCO JOURNAL</p><h2 id="blog-preview-title">A little insight before you go.</h2></div>{a('blog/index.html','<span aria-hidden="true">←</span> All blog articles','text-link')}</div><div class="blog-grid blog-grid-featured">{''.join(articlecard(article,'h3') for article in articles[:2])}</div></section>'''
def testimonial_carousel():
 reviews=testimonials['reviews']
 slides=''.join(f'''<article class="testimonial-card" role="group" aria-roledescription="slide" aria-label="{i+1} of {len(reviews)}"><p class="testimonial-rating" role="img" aria-label="{review['rating']} out of 5 stars"><span aria-hidden="true">{"★"*review['rating']}</span></p><h3>{esc(review['title'])}</h3><p class="testimonial-summary">{esc(review['summary'])}</p><div class="testimonial-person"><span class="testimonial-avatar" aria-hidden="true">{esc(review['initials'])}</span><div><strong class="testimonial-name">{esc(review['name'])}</strong><span class="testimonial-country">{esc(review['country'])}</span></div></div></article>''' for i,review in enumerate(reviews))
 dots=''.join(f'<button type="button" class="testimonial-dot" data-slide="{i}" aria-controls="testimonial-track" aria-label="Show testimonial from {esc(review["name"],quote=True)}" title="{esc(review["name"],quote=True)}"'+(' aria-current="true"' if i==0 else '')+'><span aria-hidden="true"></span></button>' for i,review in enumerate(reviews))
 return f'''<section id="testimonials" class="section container testimonials" role="region" aria-roledescription="carousel" aria-labelledby="testimonials-title"><div class="section-heading"><div><p class="eyebrow">TRAVELLER EXPERIENCES</p><h2 id="testimonials-title">The people behind the journeys.</h2></div></div><div id="testimonial-track" class="testimonial-track" tabindex="0" aria-label="Traveller testimonials">{slides}</div><div class="testimonial-controls" hidden><button type="button" class="testimonial-arrow testimonial-prev" aria-label="Previous testimonial" title="Previous testimonial" aria-controls="testimonial-track" aria-disabled="true"><span aria-hidden="true"></span></button><div class="testimonial-pagination" role="group" aria-label="Choose a testimonial">{dots}</div><button type="button" class="testimonial-arrow testimonial-next" aria-label="Next testimonial" title="Next testimonial" aria-controls="testimonial-track" aria-disabled="false"><span aria-hidden="true"></span></button></div><p class="sr-only testimonial-status" role="status" aria-live="polite" aria-atomic="true"></p><div class="testimonial-sources"><p>Review summaries from <a href="{esc(testimonials['source_url'],quote=True)}">Morocco Extra Tours</a>.</p><a class="text-link testimonial-tourradar" href="{esc(testimonials['tourradar_url'],quote=True)}">Read reviews on TourRadar <span aria-hidden="true">↗</span></a></div></section>'''

def intro(kicker,title,text):
 return f'<section class="page-intro container"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{text}</p></section>'
def legal_contact():
 return f'''<section class="legal-contact"><h2>Contact Details</h2><p>Email: <a href="mailto:{esc(site['email'],quote=True)}">{esc(site['email'])}</a><br>Phone / WhatsApp: <a href="tel:{esc(site['whatsapp'],quote=True)}">{esc(site['phone'])}</a><br>Location: {esc(site['location'])}</p><p>Last updated: October 9, 2026</p></section>'''
def crumbs(parent,label):
 return f'<nav class="breadcrumbs container" aria-label="Breadcrumb">{a("index.html","Home")}<span aria-hidden="true">/</span>{a(parent,label)}<span aria-hidden="true">/</span><span aria-current="page">Overview</span></nav>'
faqs=[('Is this a private tour?','Yes. These journeys are planned for you and the people travelling with you. The route can be adapted around your group.'),('Can we change the route or add nights?','Yes. Treat each itinerary as a starting point. Extra nights can make long driving routes more comfortable and leave more time for places you enjoy.'),('What does my quote include?','Your final proposal should confirm transport, accommodation, meals, guides, activities and any entry fees. Review the written inclusions and booking terms before making a payment.'),('Can you arrange an airport pickup?','Airport pickup and drop-off can be arranged around the agreed route. Share your flight times and accommodation so the meeting point and travel schedule can be confirmed.'),('How do we choose a desert experience?','Merzouga, Mhamid and Erg Chegaga involve different routes and travel times. Choose around the days you have available, your comfort preferences and the rest of your itinerary.')]
faq=''.join(f'<details><summary>{q}</summary><p>{v}</p></details>' for q,v in faqs)
current='index.html'
body=f'''<section class="hero">{img('sahara','A camel caravan follows a guide across the Sahara dunes at sunset','hero-photo',True)}<div class="hero-shade"></div><div class="container hero-inner"><p class="eyebrow">PRIVATE JOURNEYS · LOCAL PERSPECTIVES</p><h1>A little further.<br>A little closer<br>to <em>Morocco.</em></h1><p>From the first medina morning to the last desert sunset.<br> Discover Morocco on a journey that feels like yours.</p><div class="button-row">{a('tours/index.html','Find your journey ↗','button')}{a('plan-your-trip.html','Create your own','button outline')}</div></div><div class="hero-caption"><span>31° N / 04° W</span><span>THE SAHARA, MOROCCO</span></div></section>
<div class="promise-bar"><div class="container"><span><b>01</b> Your own private journey</span><span><b>02</b> Local knowledge, personal care</span><span><b>03</b> A route shaped around you</span></div></div>
<section class="section container" id="tours"><div class="section-heading"><div><p class="eyebrow">THE JOURNEY COLLECTION</p><h2>Different roads.<br>Extraordinary Morocco.</h2></div><div><p>Three starting points for a story of your own.<br>Find your route, then make it yours.</p>{a('tours/index.html','Explore all tours ↗','text-link')}</div></div><div class="tour-grid">{''.join(tourcard(t) for t in homepage_tours())}</div></section>
<section class="departures"><div class="container"><p class="eyebrow">BEGIN WHERE YOU LAND</p><div class="departure-row"><h2>Where do we start?</h2>{''.join(a('tours/index.html?'+urlencode({'start':city}),city+' ↗','departure-link') for city in ['Casablanca','Marrakech'])}{a('plan-your-trip.html?arrival=Fes','Fes · custom ↗','departure-link')}{a('plan-your-trip.html?arrival=Tangier','Tangier · custom ↗','departure-link')}</div></div></section>
<section class="section container" id="destinations"><div class="section-heading"><div><p class="eyebrow">MANY WORLDS, ONE MOROCCO</p><h2>Follow your curiosity.</h2></div>{a('destinations/index.html','All destinations ↗','text-link')}</div><div class="destination-grid">{''.join(destcard(next(d for d in dests if d['slug']==slug)) for slug in ['sahara','fes','ait-ben-haddou','atlas-mountains'])}</div></section>
<section class="story-section" id="about"><div class="container story-grid"><div class="story-image">{img('hospitality','Tea being poured beside a fire during a desert evening')}<span class="image-note">A warm welcome is part of the journey.</span></div><div class="story-copy"><p class="eyebrow">MOROCCO, WITH A PERSONAL TOUCH</p><h2>The places stay with you.<br>So do the people.</h2><p>There is the Morocco you come to see. And the Morocco you discover along the way: tea shared after a long drive, a conversation in the medina, a moment to stop and take it all in.</p><p>At Morocco Explorer Tours, we bring local knowledge and personal attention to private journeys. Tell us what matters to you, and we’ll help shape the route.</p>{a('about.html','Get to know us ↗','text-link')}<div class="story-values"><div><strong>Your people</strong><span>A private experience</span></div><div><strong>Your pace</strong><span>A personalised route</span></div></div></div></div></section>
<section class="section container"><div class="section-heading"><div><p class="eyebrow">FROM AN IDEA TO AN ITINERARY</p><h2>Make room for the experience.</h2></div><p>A clear plan before you go.<br>More time to enjoy being there.</p></div><div class="steps"><article><span>01 / DREAM</span><h3>Choose what draws you in</h3><p>Desert, medinas, mountains — or a little of each. Start with a route or your own wish list.</p></article><article><span>02 / SHAPE</span><h3>Bring the details together</h3><p>Match your dates and arrival city with a realistic route and the right amount of time.</p></article><article><span>03 / EXPLORE</span><h3>Know the plan, enjoy the day</h3><p>Confirm your itinerary, inclusions and pickup details before your journey begins.</p></article></div></section>
<section class="faq-section" id="questions"><div class="container faq-grid"><div><p class="eyebrow">A FEW GOOD QUESTIONS</p><h2>Before the<br>adventure begins.</h2>{a('plan-your-trip.html','Start planning ↗','text-link')}</div><div class="faq">{faq}</div></div></section>{cta()}'''
body+=testimonial_carousel()+blog_preview()
write(current,'Private Morocco Tours & Tailor-Made Journeys','Explore private Morocco tours through the Sahara, imperial cities and Atlas Mountains. Find your route and plan a personalised journey.',body,'home')
current='blog/index.html'
body=intro('THE MOROCCO JOURNAL','Morocco travel blog','Routes, seasons and everyday experiences to help you plan your own Morocco journey.')+f'<section class="container collection" aria-label="Travel articles"><div class="blog-grid">'+''.join(articlecard(article) for article in articles)+'</div></section>'+cta()
write(current,'Morocco Travel Blog: Itineraries, Sahara & Culture','Read five original Morocco travel guides covering itinerary planning, Sahara tours, seasons, Marrakech to Merzouga and local food and culture.',body,'blog-index')
for article in articles:
 current='blog/'+article['slug']+'.html'
 article_url=site['url'].rstrip('/')+'/'+current
 sections=''.join(f'<section><h2 id="{article["slug"]}-section-{i}">{esc(section["heading"])}</h2>'+''.join(f'<p>{esc(paragraph)}</p>' for paragraph in section['paragraphs'])+'</section>' for i,section in enumerate(article['sections']))
 contents=''.join(f'<li><a href="#{article["slug"]}-section-{i}">{esc(section["heading"])}</a></li>' for i,section in enumerate(article['sections']))
 source=article.get('source')
 source_note=f'<p class="article-source">Further reading: <a href="{esc(source["url"],quote=True)}">{esc(source["label"])}</a>.</p>' if source else ''
 body=f'''<nav class="breadcrumbs container" aria-label="Breadcrumb">{a('index.html','Home')}<span aria-hidden="true">/</span>{a('blog/index.html','Blog')}<span aria-hidden="true">/</span><span aria-current="page">{esc(article['category'])}</span></nav><article class="container blog-article"><header class="article-header"><p class="eyebrow">{esc(article['category'])} · MOROCCO EXPLORER TOURS</p><h1>{esc(article['title'])}</h1><p class="lead">{esc(article['intro'])}</p></header><figure class="article-image">{img(content_image(article),article['alt'],'article-photo',True)}</figure><div class="article-layout"><nav class="article-contents" aria-label="In this article"><h2>In this article</h2><ol>{contents}</ol></nav><div class="article-copy">{sections}{source_note}<section class="article-next"><h2>{esc(article['cta_title'])}</h2><p>{esc(article['cta_text'])}</p><div class="button-row">{a('tours/'+article['tour']+'.html',esc(article['tour_label'])+' ↗','button')}{a('contact.html','Enquire about your journey ↗','text-link')}</div></section>{a('blog/index.html','<span aria-hidden="true">←</span> All blog articles','text-link')}</div></div></article>'''
 schema={'@context':'https://schema.org','@type':'BlogPosting','headline':article['title'],'description':article['description'],'image':image_url(content_image(article)),'author':{'@type':'Organization','name':site['name']},'publisher':{'@type':'Organization','name':site['name']},'mainEntityOfPage':article_url,'articleSection':article['category'],'inLanguage':'en'}
 write(current,article['title'],article['description'],body,'blog-detail',schema=schema)
current='tours/index.html'
filters='''<form class="filters" id="tour-filters" hidden><label>Departure<select name="start"><option value="">All departures</option><option>Casablanca</option><option>Marrakech</option></select></label><label>Experience<select name="category"><option value="">All experiences</option><option>Sahara escapes</option><option>Cities &amp; desert</option><option>Grand journeys</option></select></label><label>Duration<select name="days"><option value="">Any length</option><option value="2">2 days</option><option value="5">5 days</option><option value="7">7 days</option></select></label><button class="text-button" type="reset">Reset filters</button></form>'''
